    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        api_base_url = str(params.get("api_base_url") or self.DEFAULT_API_BASE_URL).rstrip("/")
        timeout_seconds = float(params.get("timeout_seconds", self.DEFAULT_TIMEOUT_SECONDS) or 0.0)
        poll_interval_seconds = float(
            params.get("poll_interval_seconds", self.DEFAULT_POLL_INTERVAL_SECONDS) or 0.0
        )
        deadline = time.monotonic() + max(timeout_seconds, 0.0)

        while True:
            try:
                mailboxes = {
                    mailbox: self._fetch_mailbox_messages(
                        api_base_url=api_base_url,
                        recipient_email=mailbox,
                    )
                    for mailbox in sorted({str(spec["mailbox"]) for spec in CHECKPOINT_SPECS})
                }
                result = self._evaluate_mailboxes(mailboxes, api_base_url=api_base_url)
            except Exception as exc:
                return EvalResult(
                    status=EvalStatus.ERROR,
                    message=f"Read-only lightweight-mail query failed: {type(exc).__name__}: {exc}",
                    metadata=self._base_metadata(api_base_url),
                )
            if result.status is EvalStatus.PASS or time.monotonic() >= deadline:
                return result
            if poll_interval_seconds <= 0:
                return result
            time.sleep(min(poll_interval_seconds, max(0.0, deadline - time.monotonic())))

