    @classmethod
    def _evaluate_checkpoint(
        cls,
        spec: Mapping[str, Any],
        rows: list[dict[str, Any]],
    ) -> tuple[dict[str, Any], dict[str, Any] | None]:
        subject_rows: list[dict[str, Any]] = []
        valid_matches: list[dict[str, Any]] = []
        candidate_observations: list[dict[str, Any]] = []

        for row in rows:
            parsed = cls._parse_row(row)
            if parsed["subject"] != spec["subject"]:
                continue
            subject_rows.append(row)
            issues, evidence = cls._validate_candidate(spec, parsed)
            candidate_observations.append({"issues": issues, "evidence": evidence})
            if not issues:
                valid_matches.append({"parsed": parsed, "evidence": evidence})

        passed = len(valid_matches) == 1
        check: dict[str, Any] = {
            "name": str(spec["name"]),
            "pass": passed,
            "steps": list(spec["steps"]),
            "expected": {
                key: value
                for key, value in spec.items()
                if key not in {"name", "steps"}
            },
            "observed": {
                "target_subject_candidate_count": len(subject_rows),
                "fully_valid_match_count": len(valid_matches),
                "candidates": candidate_observations,
            },
        }
        if not passed:
            if not valid_matches:
                reason = "No message satisfies every exact field, provenance, and attachment requirement."
            else:
                reason = f"Expected one unique valid message, found {len(valid_matches)}."
            check["failure_reason"] = reason
        return check, valid_matches[0] if passed else None

    @classmethod
    def _validate_candidate(
        cls,
        spec: Mapping[str, Any],
        parsed: Mapping[str, Any],
    ) -> tuple[list[str], dict[str, Any]]:
        issues: list[str] = []
        mailbox = str(spec["mailbox"]).lower()
        if parsed["from"] != [SENDER]:
            issues.append(f"from must equal [{SENDER!r}]")
        if parsed["to"] != [mailbox]:
            issues.append(f"to must equal [{mailbox!r}]")
        if parsed["subject"] != spec["subject"]:
            issues.append("subject mismatch")
        if parsed["authored_text"] != spec["authored_text"]:
            issues.append("user-authored plain-text body mismatch")

        kind = str(spec["kind"])
        relation_sources: list[str] = []
        relation_haystacks = {
            "In-Reply-To": cls._compact_header(str(parsed["in_reply_to"])),
            "References": cls._compact_header(str(parsed["references"])),
            "quoted_original": cls._compact_header(str(parsed["quoted_text"])),
        }
        if kind == "compose":
            if parsed["in_reply_to"] or parsed["references"]:
                issues.append("ordinary composed message must not contain thread relation headers")
            if cls._looks_like_quoted_original(str(parsed["plain_text"])):
                issues.append("ordinary composed message must not masquerade as reply/forward")
        else:
            fragment = cls._compact_header(str(spec["source_message_id_fragment"]))
            source_subject = cls._compact_header(str(spec["source_subject"]))
            for source_name, haystack in relation_haystacks.items():
                if fragment in haystack or (source_name == "quoted_original" and source_subject in haystack):
                    relation_sources.append(source_name)
            if not relation_sources:
                issues.append("reply/forward is not bound to the required seed message")

        expected_attachments = list(spec["attachments"])
        observed_attachments = list(parsed["attachments"])
        if len(observed_attachments) != len(expected_attachments):
            issues.append(
                f"attachment count must be {len(expected_attachments)}, got {len(observed_attachments)}"
            )
        elif expected_attachments:
            expected = expected_attachments[0]
            observed = observed_attachments[0]
            if expected.get("filename") is not None and observed["filename"] != expected["filename"]:
                issues.append("attachment filename mismatch")
            if observed["content_type"] != expected["content_type"]:
                issues.append("attachment content type mismatch")
            if observed["sha256"] != expected["sha256"]:
                issues.append("attachment SHA-256 mismatch")

        if parsed["parsed_date"] is None:
            issues.append("Date header is missing or unparseable")
        if parsed["uid"] is None:
            issues.append("mailbox UID is missing or non-numeric")

        evidence = {
            "mailbox": spec["mailbox"],
            "uid": parsed["uid"],
            "date": parsed["date"],
            "parsed_date": (
                parsed["parsed_date"].isoformat() if parsed["parsed_date"] is not None else None
            ),
            "from": parsed["from"],
            "to": parsed["to"],
            "subject": parsed["subject"],
            "authored_text": parsed["authored_text"],
            "relation_sources": relation_sources,
            "attachments": observed_attachments,
        }
        return issues, evidence

    @classmethod
    def _parse_row(cls, row: Mapping[str, Any]) -> dict[str, Any]:
        raw = row.get("mimeMessage")
        if not isinstance(raw, str):
            raw = ""
        message = BytesParser(policy=policy.default).parsebytes(raw.encode("utf-8"))
        plain_text = cls._plain_text(message)
        authored_text, quoted_text = cls._split_authored_text(plain_text)
        date_value = str(message.get("Date") or "")
        parsed_date = cls._parse_date(date_value)
        try:
            uid = int(row.get("uid"))
        except (TypeError, ValueError):
            uid = None
        return {
            "uid": uid,
            "date": date_value,
            "parsed_date": parsed_date,
            "from": cls._addresses(message, "From"),
            "to": cls._addresses(message, "To"),
            "subject": str(message.get("Subject") or row.get("subject") or ""),
            "plain_text": plain_text,
            "authored_text": authored_text,
            "quoted_text": quoted_text,
            "in_reply_to": cls._raw_header(message, "In-Reply-To"),
            "references": cls._raw_header(message, "References"),
            "attachments": cls._attachments(message),
        }

    @staticmethod
    def _raw_header(message: Message, name: str) -> str:
        # Wire value, not the policy.default structured header: from Python
        # 3.13 that rewrites the doubled-domain seed ids (``<a@b@c>``) on parse.
        wanted = name.lower()
        for key, value in message.raw_items():
            if key.lower() == wanted:
                return str(value)
        return ""

    @staticmethod
    def _addresses(message: Message, header: str) -> list[str]:
        return [
            address.lower()
            for _name, address in getaddresses(message.get_all(header, []))
            if address
        ]

    @staticmethod
    def _plain_text(message: Message) -> str:
        parts = message.walk() if message.is_multipart() else (message,)
        for part in parts:
            if part.get_content_type() != "text/plain":
                continue
            if part.get_content_disposition() == "attachment":
                continue
            try:
                content = part.get_content()
            except (LookupError, UnicodeError):
                payload = part.get_payload(decode=True) or b""
                content = payload.decode(part.get_content_charset() or "utf-8", errors="replace")
            return str(content).replace("\r\n", "\n").replace("\r", "\n")
        return ""

    @staticmethod
    def _split_authored_text(plain_text: str) -> tuple[str, str]:
        marker_patterns = (
            r">\s*On\s+.+?wrote:",
            r">?\s*-{5,}\s*Original Message\s*-{5,}",
        )
        starts = [
            match.start()
            for pattern in marker_patterns
            if (match := re.search(pattern, plain_text, flags=re.IGNORECASE | re.DOTALL))
        ]
        if not starts:
            return plain_text.strip(), ""
        index = min(starts)
        return plain_text[:index].strip(), plain_text[index:].strip()

    @staticmethod
    def _looks_like_quoted_original(text: str) -> bool:
        lowered = text.lower()
        return "original message" in lowered or bool(re.search(r">\s*on\s+.+?wrote:", text, re.I | re.S))

    @staticmethod
    def _compact_header(value: str) -> str:
        return re.sub(r"\s+", "", value).lower()

    @staticmethod
    def _parse_date(value: str) -> datetime | None:
        try:
            parsed = parsedate_to_datetime(value)
        except (TypeError, ValueError, OverflowError):
            return None
        if parsed is None:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _attachments(message: Message) -> list[dict[str, Any]]:
        attachments: list[dict[str, Any]] = []
        for part in message.walk():
            if part.is_multipart():
                continue
            filename = part.get_filename()
            if part.get_content_disposition() != "attachment" and filename is None:
                continue
            payload = part.get_payload(decode=True) or b""
            attachments.append(
                {
                    "filename": filename,
                    "content_type": part.get_content_type().lower(),
                    "size": len(payload),
                    "sha256": hashlib.sha256(payload).hexdigest(),
                }
            )
        return attachments

    @staticmethod
    def _global_order_check(matches: list[dict[str, Any] | None]) -> dict[str, Any]:
        evidence = [match["evidence"] if match is not None else None for match in matches]
        parsed_dates = [
            match["parsed"]["parsed_date"] if match is not None else None for match in matches
        ]
        passed = all(value is not None for value in parsed_dates) and all(
            parsed_dates[index] < parsed_dates[index + 1]
            for index in range(len(parsed_dates) - 1)
        )
        check: dict[str, Any] = {
            "name": "global_delivery_date_order",
            "pass": passed,
            "steps": [7, 15, 23, 28, 37, 45, 54, 63, 68, 76],
            "observed": evidence,
        }
        if not passed:
            check["failure_reason"] = "Matched message Date values are not all present and strictly increasing."
        return check

    @staticmethod
    def _mailbox_uid_order_check(matches: list[dict[str, Any] | None]) -> dict[str, Any]:
        by_mailbox: dict[str, list[dict[str, Any]]] = {}
        complete = all(match is not None for match in matches)
        for match in matches:
            if match is None:
                continue
            evidence = match["evidence"]
            by_mailbox.setdefault(str(evidence["mailbox"]), []).append(
                {"uid": evidence["uid"], "subject": evidence["subject"]}
            )
        passed = complete and all(
            all(
                rows[index]["uid"] is not None
                and rows[index + 1]["uid"] is not None
                and rows[index]["uid"] < rows[index + 1]["uid"]
                for index in range(len(rows) - 1)
            )
            for rows in by_mailbox.values()
        )
        check: dict[str, Any] = {
            "name": "same_mailbox_uid_order",
            "pass": passed,
            "steps": [7, 15, 23, 28, 37, 45, 54, 63, 68, 76],
            "observed": by_mailbox,
        }
        if not passed:
            check["failure_reason"] = "Matched UIDs are not all present and strictly increasing within each mailbox."
        return check

    @staticmethod
    def _duplicate_covered_steps() -> list[int]:
        counts: dict[int, int] = {}
        for group in STEP_GROUPS:
            for raw_step in group["steps"]:
                step = int(raw_step)
                counts[step] = counts.get(step, 0) + 1
        return sorted(step for step, count in counts.items() if count != 1)

    @staticmethod
    def _step_coverage_records(
        checkpoint_checks: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        checks_by_name = {str(check["name"]): check for check in checkpoint_checks}
        records: list[dict[str, Any]] = []
        for group in STEP_GROUPS:
            checkpoint_name = str(group["checkpoint"])
            checkpoint_passed = checks_by_name.get(checkpoint_name, {}).get("pass") is True
            for raw_step in group["steps"]:
                records.append(
                    {
                        "step": int(raw_step),
                        "pass": checkpoint_passed,
                        "checkpoint_names": [checkpoint_name],
                        "dimensions": {
                            "final_object": "unique delivered MIME message",
                            "content": "exact sender, recipient, subject, authored text, and attachment rules",
                            "source_or_process": "thread provenance plus strict Date/UID sequence",
                            "final_ui": "not required and not claimed",
                        },
                        "mapping_basis": (
                            "This step belongs to a composite send chain whose final durable message "
                            "covers all inputs, attachment selection, and send completion."
                        ),
                    }
                )
        return sorted(records, key=lambda record: record["step"])

    @staticmethod
    def _fetch_mailbox_messages(
        *,
        api_base_url: str,
        recipient_email: str,
        mailbox: str = "INBOX",
    ) -> list[dict[str, Any]]:
        encoded_user = quote(recipient_email, safe="")
        encoded_mailbox = quote(mailbox, safe="")
        request = Request(
            f"{api_base_url}/api/user/{encoded_user}/messages/{encoded_mailbox}",
            method="GET",
        )
        if request.get_method() != "GET":
            raise RuntimeError("strict read-only evaluator attempted a non-GET request")
        try:
            with urlopen(request, timeout=5.0) as response:
                payload = response.read()
        except (HTTPError, URLError) as exc:
            raise RuntimeError(f"GET mailbox failed for {recipient_email}: {exc}") from exc
        data = json.loads(payload.decode("utf-8"))
        if not isinstance(data, list):
            raise RuntimeError(f"mailbox payload must be a list, got {type(data)!r}")
        return [message for message in data if isinstance(message, dict)]
